-- Synthetic-only acceptance; rolls back every record and is safe on the hosted schema.
begin;
create function pg_temp.expect(ok boolean,label text)returns void language plpgsql as $$begin
 if ok is not true then raise exception 'FAIL: %',label;end if;
 perform set_config('folio.rules_checks',(coalesce(nullif(current_setting('folio.rules_checks',true),''),'0')::int+1)::text,true);
end$$;
create function pg_temp.deny(statement text,label text)returns void language plpgsql as $$begin
 begin execute statement;exception when others then perform pg_temp.expect(true,label);return;end;
 raise exception 'FAIL: % accepted',label;
end$$;
with u as(insert into auth.users(id,email)values(gen_random_uuid(),'rules-a@example.invalid')returning id)select set_config('folio.rules_a',id::text,true)from u;
with u as(insert into auth.users(id,email)values(gen_random_uuid(),'rules-b@example.invalid')returning id)select set_config('folio.rules_b',id::text,true)from u;
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('folio.rules_a'),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('folio.rules_a'),'is_anonymous',false)::text,true);
select public.initialize_workspace();
with a as(insert into public.accounts(name,type,opening_balance_paise)values('Synthetic rules bank','bank',500000)returning id)select set_config('folio.rules_bank',id::text,true)from a;
select set_config('folio.rules_cat',(select id::text from public.categories where kind='expense' limit 1),true);
with s as(insert into public.subscriptions(name,amount_paise,cadence,next_due_on,account_id)values('Synthetic subscription',2500,'monthly',folio_private.today(),current_setting('folio.rules_bank')::uuid)returning id)select set_config('folio.rules_sub',id::text,true)from s;
with r as(insert into public.statement_rules(account_id,recipient_key,recipient_name,direction,kind,category_id)values(current_setting('folio.rules_bank')::uuid,'kotak-upi:ABCD:SYNTHETIC CAFE','Synthetic cafe','debit','expense',current_setting('folio.rules_cat')::uuid)returning id)select set_config('folio.rules_rule',id::text,true)from r;
select pg_temp.expect((select count(*)=1 from public.statement_rules),'owner reads own rule');
select pg_temp.expect((select count(*)=0 from public.transactions),'saving rule never imports financial records');
select pg_temp.expect((select balance_paise='500000' from jsonb_array_elements(public.workspace_snapshot()->'accounts')a cross join lateral(select a->>'balance_paise' balance_paise)b where a->>'id'=current_setting('folio.rules_bank')),'rule does not change balances');
update public.statement_rules set enabled=false where id=current_setting('folio.rules_rule')::uuid;
select pg_temp.expect((select not enabled from public.statement_rules where id=current_setting('folio.rules_rule')::uuid),'owner can disable');
insert into public.statement_rules(account_id,recipient_key,recipient_name,direction,kind,category_id)values(current_setting('folio.rules_bank')::uuid,'kotak-upi:ABCD:SYNTHETIC CAFE','Synthetic cafe','debit','expense',current_setting('folio.rules_cat')::uuid)
on conflict(account_id,direction,recipient_key,amount_paise,match_day) do update set enabled=true;
select pg_temp.expect((select count(*)=1 and bool_and(enabled) from public.statement_rules),'nullable amount upsert is deterministic');
select pg_temp.deny(format('update public.statement_rules set match_day=32 where id=%L',current_setting('folio.rules_rule')),'invalid deduction day rejected');
select pg_temp.deny(format('update public.statement_rules set match_day=0 where id=%L',current_setting('folio.rules_rule')),'zero deduction day rejected');
update public.statement_rules set match_day=17 where id=current_setting('folio.rules_rule')::uuid;
select pg_temp.expect((select match_day=17 from public.statement_rules where id=current_setting('folio.rules_rule')::uuid),'deduction day persists');
update public.statement_rules set match_day=null where id=current_setting('folio.rules_rule')::uuid;
select pg_temp.deny(format('update public.statement_rules set user_id=%L where id=%L',current_setting('folio.rules_b'),current_setting('folio.rules_rule')),'rule cannot be reassigned to another owner');
select pg_temp.deny(format('update public.statement_rules set direction=''credit'' where id=%L',current_setting('folio.rules_rule')),'expense rule cannot match credits');
select pg_temp.deny(format('update public.statement_rules set subscription_id=%L where id=%L',current_setting('folio.rules_sub'),current_setting('folio.rules_rule')),'subscription requires exact amount');
select pg_temp.deny(format('update public.statement_rules set kind=''loan_payment'' where id=%L',current_setting('folio.rules_rule')),'invalid target shape rejected');
select set_config('folio.rules_rows',jsonb_build_array(jsonb_build_object('source_row','1:4','entry',jsonb_build_object('occurred_on',folio_private.today(),'kind','expense','amount_paise',2500,'category_id',current_setting('folio.rules_cat'),'description','Synthetic recurring merchant','subscription_id',current_setting('folio.rules_sub'))))::text,true);
select pg_temp.deny(format('select public.preview_statement_import(%L,repeat(''a'',64),%L)',current_setting('folio.rules_bank'),jsonb_set(current_setting('folio.rules_rows')::jsonb,'{0,entry,unexpected}','true')::text),'linked expense rejects unknown fields');
select pg_temp.deny(format('select public.preview_statement_import(%L,repeat(''a'',64),%L)',current_setting('folio.rules_bank'),jsonb_set(current_setting('folio.rules_rows')::jsonb,'{0,entry,kind}','"income"')::text),'subscription cannot be linked to income');
update public.subscriptions set active=false where id=current_setting('folio.rules_sub')::uuid;
select pg_temp.deny(format('select public.preview_statement_import(%L,repeat(''a'',64),%L)',current_setting('folio.rules_bank'),current_setting('folio.rules_rows')),'inactive subscription cannot be imported');
update public.subscriptions set active=true where id=current_setting('folio.rules_sub')::uuid;
select set_config('folio.rules_request',gen_random_uuid()::text,true);
select pg_temp.expect(public.preview_statement_import(current_setting('folio.rules_bank')::uuid,repeat('a',64),current_setting('folio.rules_rows')::jsonb)->'duplicates'='[false]'::jsonb,'linked expense preview supported');
select pg_temp.expect((select count(*)=0 from public.transactions),'preview never posts');
select pg_temp.expect(public.import_statement_entries(current_setting('folio.rules_bank')::uuid,repeat('a',64),current_setting('folio.rules_rows')::jsonb,current_setting('folio.rules_request')::uuid)='{"inserted":1,"skipped":0}'::jsonb,'subscription import is atomic');
select pg_temp.expect((select count(*)=1 from public.transactions where subscription_id=current_setting('folio.rules_sub')::uuid and amount_paise=-2500),'one expense linked to subscription');
select pg_temp.expect((select count(*)=1 from jsonb_array_elements(public.workspace_snapshot()->'deductions')d where d->>'commitment_id'=current_setting('folio.rules_sub') and d->>'paid_on'=folio_private.today()::text),'actual deduction date appears in monthly plan');
select pg_temp.expect(public.import_statement_entries(current_setting('folio.rules_bank')::uuid,repeat('a',64),current_setting('folio.rules_rows')::jsonb,current_setting('folio.rules_request')::uuid)='{"inserted":1,"skipped":0}'::jsonb,'retry reuses receipt');
select pg_temp.expect(public.import_statement_entries(current_setting('folio.rules_bank')::uuid,repeat('b',64),current_setting('folio.rules_rows')::jsonb,gen_random_uuid())='{"inserted":0,"skipped":1}'::jsonb,'different PDF cannot duplicate linked subscription');
select pg_temp.deny(format('select public.import_statement_entries(%L,repeat(''a'',64),%L,%L)',current_setting('folio.rules_bank'),jsonb_set(current_setting('folio.rules_rows')::jsonb,'{0,entry,amount_paise}','2600')::text,current_setting('folio.rules_request')),'changed payload cannot reuse receipt');
select set_config('folio.rules_bad_rows',(current_setting('folio.rules_rows')::jsonb || jsonb_build_array(jsonb_build_object('source_row','1:5','entry',jsonb_build_object('occurred_on',folio_private.today(),'kind','expense','amount_paise',2600,'category_id',current_setting('folio.rules_cat'),'description','Synthetic invalid linked row','subscription_id',gen_random_uuid()))))::text,true);
select pg_temp.deny(format('select public.import_statement_entries(%L,repeat(''c'',64),%L,gen_random_uuid())',current_setting('folio.rules_bank'),current_setting('folio.rules_bad_rows')),'unavailable subscription aborts whole batch');
select pg_temp.expect((select count(*)=1 from public.transactions),'failed batch leaves ledger unchanged');
select set_config('request.jwt.claim.sub',current_setting('folio.rules_b'),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('folio.rules_b'),'is_anonymous',false)::text,true);
select public.initialize_workspace();
with a as(insert into public.accounts(name,type)values('Synthetic other bank','bank')returning id)select set_config('folio.rules_bank_b',id::text,true)from a;
select pg_temp.expect((select count(*)=0 from public.statement_rules),'owner cannot read other rules');
select pg_temp.deny(format('insert into public.statement_rules(account_id,recipient_key,recipient_name,direction,kind)values(%L,''synthetic-key'',''Synthetic'',''debit'',''exclude'')',current_setting('folio.rules_bank')),'cross-owner account rule rejected');
select pg_temp.deny(format('insert into public.statement_rules(account_id,recipient_key,recipient_name,direction,kind,category_id)values(%L,''synthetic-key'',''Synthetic'',''debit'',''expense'',%L)',current_setting('folio.rules_bank_b'),current_setting('folio.rules_cat')),'cross-owner category rejected');
select pg_temp.deny(format('select public.preview_statement_import(%L,repeat(''a'',64),%L)',current_setting('folio.rules_bank_b'),current_setting('folio.rules_rows')),'cross-owner subscription rejected');
update public.statement_rules set enabled=false where id=current_setting('folio.rules_rule')::uuid;
delete from public.statement_rules where id=current_setting('folio.rules_rule')::uuid;
select set_config('request.jwt.claim.sub',current_setting('folio.rules_a'),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('folio.rules_a'),'is_anonymous',false)::text,true);
select pg_temp.expect((select enabled from public.statement_rules where id=current_setting('folio.rules_rule')::uuid),'other owner cannot update or delete rule');
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('folio.rules_a'),'is_anonymous',true)::text,true);
select pg_temp.deny('select * from public.statement_rules','anonymous JWT cannot access rules');
reset role;
select pg_temp.expect(not has_table_privilege('anon','public.statement_rules','select'),'anonymous role has no grant');
select current_setting('folio.rules_checks')||' remembered rule assertions passed';
rollback;
